using UnityEngine;

namespace Neram.Unity
{
    /// <summary>Free-roam navigation volume generated by setup: the room interior (isRoom) or a keep-out box around the
    /// patient/table or a piece of equipment. Read by CameraRig.CollectNavigation.</summary>
    [DisallowMultipleComponent]
    public sealed class NeramNavVolume : MonoBehaviour
    {
        public Vector3 halfExtents = new Vector3(0.5f, 0.5f, 0.5f);
        public bool isRoom;
    }
}
